import * as THREE from 'three';
import GameLoop from '../shared/core/GameLoop.js';
import EventBus from '../shared/core/EventBus.js';
import InputController from '../shared/core/InputController.js';
import MemoryRegistry from '../shared/core/MemoryRegistry.js';
import RendererFactory from '../shared/render/RendererFactory.js';
import { PostFX } from '../shared/render/PostFX.js';
import { CameraRig } from '../shared/render/CameraRig.js';
import { ParticleManager } from '../shared/vfx/ParticleManager.js';
import { ShockwaveRingPool } from '../shared/vfx/ShockwaveRingPool.js';
import { MotionTrailPool } from '../shared/vfx/MotionTrailPool.js';
import { FloatingTextPool } from '../shared/vfx/FloatingTextPool.js';
import { AudioEngine } from '../shared/audio/AudioEngine.js';
import { GlassUI } from '../shared/ui/GlassUI.js';
import HUD from '../shared/ui/HUD.js';
import PlayerShip from './entities/PlayerShip.js';
import InvaderFormation from './entities/InvaderFormation.js';
import PlayerBullet from './entities/PlayerBullet.js';
import InvaderBullet from './entities/InvaderBullet.js';
import BunkerManager from './entities/Bunker.js';
import UFO from './entities/UFO.js';
import PowerUp from './entities/PowerUp.js';
import Playfield from './world/Playfield.js';
import Starfield from './world/Starfield.js';
import PowerUpSystem from './systems/PowerUpSystem.js';
import WaveSystem from './systems/WaveSystem.js';
import { circleHit, pointInAABB, pointAABB, segCircle, segAABB } from './systems/CollisionSystem.js';
import { BOUNDS, PLAYER, FORMATION, BUNKERS, INVADER_BULLETS, SCORING, VFX, COLORS, POWERUPS } from './config.js';

const HS_KEY = 'space_invaders_highscore';

export default class SpaceInvadersGame {
  /**
   * @param {HTMLElement} root the game container element
   */
  constructor(root) {
    this.root = root;
    this.state = 'READY';
    this.score = 0;
    this.highScore = this._loadHigh();
    this.lives = 3;
    this.combo = 1;
    this.wave = 1;
    this.time = 0;
    this._fireTimer = 0;
    this._lastInput = { axisX: 0, firePressed: false, pausePressed: false, startPressed: false };
    // DEBUG: firing/hit counters (remove before final)
    this._dbg = { inputFireFrames: 0, fires: 0, invaderHits: 0, bunkerHits: 0, playerHits: 0 };

    // ── Core ─────────────────────────────────────────────────────
    this.registry = new MemoryRegistry();
    this.bus = new EventBus();
    this.scene = new THREE.Scene();
    this.scene.background = new THREE.Color(0x04060d);
    this.scene.fog = new THREE.Fog(0x04060d, 40, 120);

    this.renderer = RendererFactory.createRenderer({
      container: root,
      registry: this.registry,
      fov: 42,
      near: 0.1,
      far: 200,
      exposure: 1.1,
    });
    this.camera = RendererFactory.createCamera({ fov: 42, near: 0.1, far: 200, aspect: root.clientWidth / Math.max(1, root.clientHeight) });
    this.postFX = new PostFX(this.renderer, this.scene, this.camera, this.registry);
    this.cameraRig = new CameraRig(this.camera, { maxAmplitude: 0.6, decay: 1.4, kickDecay: 6.0 });
    this.cameraRig.setBase(new THREE.Vector3(0, 2.2, 15), new THREE.Vector3(0, 0.5, 0));

    // ── VFX ──────────────────────────────────────────────────────
    this.particles = new ParticleManager(this.scene, this.registry);
    this.rings = new ShockwaveRingPool(this.scene, this.registry, { max: VFX.ringCap });
    this.trails = new MotionTrailPool({ parent: this.scene, registry: this.registry, count: VFX.trailCap });
    this.text = new FloatingTextPool(this.scene, { htmlContainer: root });

    // ── World ────────────────────────────────────────────────────
    this.playfield = new Playfield(this.scene, this.registry);
    this.starfield = new Starfield(this.scene, this.registry);

    // ── Entities ─────────────────────────────────────────────────
    this.player = new PlayerShip(this.scene, this.registry);
    this.formation = new InvaderFormation(this.scene, this.registry);
    this.playerBullets = new PlayerBullet(this.scene, this.registry, this.trails);
    this.invaderBullets = new InvaderBullet(this.scene, this.registry, this.trails);
    this.bunkers = new BunkerManager(this.scene, this.registry);
    this.ufo = new UFO(this.scene, this.registry, this.trails);
    this.powerups = new PowerUp(this.scene, this.registry);

    // ── Systems ──────────────────────────────────────────────────
    this.powerUpSystem = new PowerUpSystem();
    this.waveSystem = new WaveSystem();

    // ── Audio ────────────────────────────────────────────────────
    this.audio = new AudioEngine({ masterVolume: 0.8, musicVolume: 0.5, sfxVolume: 0.9 });

    // ── UI ───────────────────────────────────────────────────────
    this.hud = new HUD(root, { gameName: 'SPACE INVADERS' });
    this.readyPanel = this._buildReadyPanel();
    this.pausePanel = this._buildPausePanel();
    this.gameOverPanel = this._buildGameOverPanel();

    // ── Input ────────────────────────────────────────────────────
    this.input = new InputController();
    this.input.attach();

    // ── Loop ─────────────────────────────────────────────────────
    this.loop = new GameLoop({ step: 1 / 60, maxSubSteps: 5, update: (dt) => this._update(dt) });

    // ── Wiring ───────────────────────────────────────────────────
    this.player.fire = (x, y) => {
      const cap = this.powerUpSystem.maxBullets(PLAYER.maxBullets);
      if (this.playerBullets.activeCount() >= cap) return;
      this.playerBullets.fire(x, y);
      this.audio.playSfx('laser', { volume: 0.7, pitch: 1 });
    };

    // Debug hook for test tooling (removed before final).
    if (typeof window !== 'undefined') window.__gameInternal = this;

    this._onVis = () => {
      if (document.hidden && this.state === 'PLAYING') this._setPaused(true);
    };
    document.addEventListener('visibilitychange', this._onVis);

    this._onResize = RendererFactory.bindResize(this.renderer, this.camera, {
      container: root,
      onResize: (w, h) => this.postFX.setSize(w, h),
    });

    // Debug hook: expose the live instance so tooling/tests can inspect state.
    if (typeof window !== 'undefined') window.__gameInstance = this;

    // ── Initial state ────────────────────────────────────────────
    window.__gameInstance = this; // debug hook (overwritten by index.html)
    this.formation.reset(this.waveSystem.topY(), 1);
    this.bunkers.reset();
    this.player.reset(0);
    this.hud.setHigh(this.highScore);
    this._showReady();
  }

  // ── Public API (GameContract) ──────────────────────────────────
  start() {
    this.audio.resume();
    this.loop.start();
  }

  pause() { this._setPaused(true); }
  resume() { this._setPaused(false); }

  destroy() {
    this.loop.stop();
    this.input.detach();
    document.removeEventListener('visibilitychange', this._onVis);
    if (this._onResize) this._onResize();
    this.audio.dispose();
    this.playerBullets.releaseAll();
    this.invaderBullets.releaseAll();
    this.powerups.releaseAll();
    this.particles.clear();
    this.rings.clear();
    this.trails.clear();
    this.text.clear();
    // Dispose entity/VFX meshes first (they free their own GPU buffers),
    // then the registry (shared geometries/materials/textures), then the
    // renderer last so every gl.* delete happens on a live context.
    this.player.dispose();
    this.formation.dispose();
    this.playerBullets.dispose();
    this.invaderBullets.dispose();
    this.bunkers.dispose();
    this.ufo.dispose();
    this.powerups.dispose();
    this.playfield.dispose();
    this.starfield.dispose();
    this.particles.dispose();
    this.rings.dispose();
    this.trails.dispose();
    this.text.dispose();
    this.hud.dispose();
    this.readyPanel.dispose();
    this.pausePanel.dispose();
    this.gameOverPanel.dispose();
    this.postFX.dispose();
    // Untrack the renderer so disposeAll() does NOT destroy the WebGL context
    // while geometries/materials/textures are still being deleted (that would
    // log INVALID_OPERATION warnings). Dispose the renderer last, after every
    // GPU resource it owns has been freed.
    this.registry.remove(this.renderer);
    this.registry.disposeAll();
    this.renderer.dispose();
    this.bus.clear();
  }

  // ── State transitions ──────────────────────────────────────────
  _showReady() {
    this.state = 'READY';
    this.readyPanel.show();
    this.pausePanel.hide();
    this.gameOverPanel.hide();
    this.hud.el.style.display = 'none';
    this.player.group.visible = false;
    this._readyPanel.setStat('HIGH SCORE', String(this.highScore).padStart(6, '0'));
  }

  _startGame() {
    this.audio.playSfx('uiClick', { volume: 0.5 });
    this.cameraRig.setBase(new THREE.Vector3(0, 2.2, 15), new THREE.Vector3(0, 0.5, 0));
    this.score = 0;
    this.lives = 3;
    this.combo = 1;
    this.wave = 1;
    this.waveSystem.setWave(1);
    this.powerUpSystem.clear();
    this.playerBullets.releaseAll();
    this.invaderBullets.releaseAll();
    this.powerups.releaseAll();
    this.formation.reset(this.waveSystem.topY(), 1);
    this.bunkers.reset();
    this.player.reset(0);
    this.player.invulnerable = 2.0;
    this.hud.setScore(0);
    this.hud.setLives(3);
    this.hud.setWave(1);
    this.hud.setCombo(1);
    this.hud.el.style.display = '';
    this.readyPanel.hide();
    this.pausePanel.hide();
    this.gameOverPanel.hide();
    this.state = 'PLAYING';
    this.audio.startMusic('invaders');
    this._banner('WAVE 1');
  }

  _setPaused(on) {
    if (on) {
      if (this.state !== 'PLAYING') return;
      this.state = 'PAUSED';
      this.loop.pause();
      this.pausePanel.show();
    } else {
      if (this.state !== 'PAUSED') return;
      this.state = 'PLAYING';
      this.loop.resume();
      this.pausePanel.hide();
    }
  }

  _gameOver() {
    this.state = 'GAMEOVER';
    this.audio.stopMusic();
    this.audio.playSfx('gameover', { volume: 0.8 });
    if (this.score > this.highScore) {
      this.highScore = this.score;
      this._saveHigh(this.highScore);
    }
    this.hud.setHigh(this.highScore);
    this._gameOverPanel.setStat('SCORE', String(this.score).padStart(6, '0'));
    this._gameOverPanel.setStat('HIGH', String(this.highScore).padStart(6, '0'));
    this.gameOverPanel.show();
  }

  _waveClear() {
    const bonus = this.waveSystem.waveBonus();
    this._addScore(bonus);
    this._banner(`WAVE CLEAR  +${bonus}`);
    this.audio.playSfx('score', { volume: 0.8, pitch: 1.2 });
    this._nextWave();
  }

  _nextWave() {
    this.wave++;
    this.waveSystem.setWave(this.wave);
    this.formation.reset(this.waveSystem.topY(), this.wave);
    this.bunkers.reset();
    this.playerBullets.releaseAll();
    this.invaderBullets.releaseAll();
    this.powerups.releaseAll();
    this.player.invulnerable = 2.0;
    this.hud.setWave(this.wave);
    this._banner(`WAVE ${this.wave}`);
  }

  // ── Main update ────────────────────────────────────────────────
  _update(dt) {
    this.time += dt;
    const input = this.input.poll();
    this._lastInput = input;

    if (input.pausePressed) this._togglePause();
    if (input.startPressed) this._onStart();

    if (this.state === 'READY') {
      this._updateReady(dt);
    } else if (this.state === 'PLAYING') {
      this._updatePlaying(dt, input);
    }
    // PAUSED / GAMEOVER: no sim update (loop is paused or state frozen)

    // VFX + camera always update (even in READY for the attract feel)
    this.cameraRig.update(dt, this.time);
    this.particles.update(dt, this.camera);
    this.rings.update(dt);
    this.trails.update(dt);
    this.text.update(dt, this.camera);
    this.playfield.update(dt, this.time, this.player.x);
    this.starfield.update(dt, this.time);

    this.postFX.render();
  }

  _updateReady(dt) {
    // Attract mode: formation marches + fires, no player.
    this.formation.update(dt);
    this._fireTimer -= dt;
    if (this._fireTimer <= 0 && this.formation.alive > 0) {
      this._spawnInvaderBullet();
      this._fireTimer = this.waveSystem.fireInterval();
    }
    const live = this.invaderBullets.update(dt, 0);
    for (const m of live) {
      if (m.position.y < BOUNDS.bottom - 1) this.invaderBullets.releaseBullet(m);
    }
    // Slow camera orbit — drive the rig's base pose so cameraRig.update()
    // (which runs after this) composes the shake on top of the orbit.
    const a = this.time * 0.15;
    this.cameraRig.setBase(
      this._v3(Math.sin(a) * 3, 2.2 + Math.sin(this.time * 0.1) * 0.5, 15),
      this._v3(0, 0.5, 0)
    );
  }

  _updatePlaying(dt, input) {
    // Player
    this.player.update(dt, input.axisX, this.time);
    // Fire on the HELD state (level), not the edge — the original arcade game
    // auto-fires while Space is held, and a held key is far more robust than an
    // edge trigger (a keydown+keyup that both land between two polls would be
    // missed by an edge test). tryFire() gates on the cooldown, so holding
    // Space fires at the fire rate rather than every frame.
    if (input.fire && this.player.alive) {
      this.player.tryFire(this.powerUpSystem.fireCooldown(PLAYER.fireCooldown));
    }

    // Formation (SLOW power-up lengthens the step interval)
    this.formation.speedMul = this.powerUpSystem.slowFactor();
    this.formation.update(dt);

    // Player bullets
    const pBullets = this.playerBullets.update(dt);

    // Invader bullets
    this._fireTimer -= dt;
    if (this._fireTimer <= 0 && this.formation.alive > 0) {
      this._spawnInvaderBullet();
      this._fireTimer = this.waveSystem.fireInterval();
    }
    const iBullets = this.invaderBullets.update(dt, this.player.x);

    // UFO
    const ufoSpawned = this.ufo.update(dt);
    if (ufoSpawned) this.audio.playSfx('siren', { volume: 0.5, duration: 0.8 });

    // Power-ups
    const livePU = this.powerups.update(dt);

    // Bunker flush (erosion)
    this.bunkers.flush();

    // Collisions
    this._collide(pBullets, iBullets, livePU);

    // Power-up timers
    this.powerUpSystem.update(dt);
    this.hud.setEffects(this.powerUpSystem.hudEffects());

    // Game-over check: formation reached the player line
    if (this.formation.bottomY() <= BOUNDS.gameOverY) {
      this._gameOver();
      return;
    }

    // Wave clear
    if (this.formation.alive === 0) {
      this._waveClear();
    }

    // Music intensity tracks wave + remaining invaders
    const intensity = Math.min(1, 0.3 + (this.wave - 1) * 0.04 + (1 - this.formation.alive / 55) * 0.3);
    this.audio.setMusicIntensity(intensity);
  }

  // ── Invader bullet spawning ────────────────────────────────────
  _spawnInvaderBullet() {
    const cols = this.formation.bottomByColumn();
    const live = [];
    for (let c = 0; c < cols.length; c++) if (cols[c]) live.push(c);
    if (live.length === 0) return;
    const col = live[(Math.random() * live.length) | 0];
    const pos = cols[col];
    const speed = this.waveSystem.bulletSpeed() * this.powerUpSystem.bulletSpeedMul();
    let behavior = 'straight';
    const r = Math.random();
    if (r < this.waveSystem.seekerChance()) behavior = 'seeker';
    else if (r < this.waveSystem.seekerChance() + this.waveSystem.zigzagChance()) behavior = 'zigzag';
    this.invaderBullets.spawn(pos.x, pos.y, speed, behavior);
  }

  // ── Collision resolution ───────────────────────────────────────
  // Bullets move fast, so every bullet-vs-target test is a SWEEPED test
  // (segment from last frame's position to this frame's) — a point test at
  // the new position alone would let a fast bullet tunnel straight through
  // a 1-unit target in a single frame.
  _collide(pBullets, iBullets, livePU) {
    const bodyR = FORMATION.bodyHalf;
    const playerR = PLAYER.halfWidth;

    // Player bullets vs invaders (swept)
    for (const m of pBullets) {
      const hit = this.formation.findInvaderSeg(
        m.prevX, m.prevY, m.position.x, m.position.y, PLAYER.bulletRadius + bodyR
      );
      if (hit) {
        this._onInvaderHit(hit, m.position.x, m.position.y);
        this.playerBullets.releaseBullet(m);
        continue;
      }
      // Player bullets vs bunkers (swept against the bunker AABB, then erode)
      let consumed = false;
      for (let i = 0; i < this.bunkers.bunkers.length; i++) {
        const b = this.bunkers.bunkers[i];
        if (b.isDestroyed) continue;
        const aabb = b.aabb();
        if (segAABB(m.prevX, m.prevY, m.position.x, m.position.y, aabb)) {
          const n = this.bunkers.erode(i, m.position.x, m.position.y, BUNKERS.erodeRadiusBullet, BUNKERS.erodeFalloff);
          if (n > 0) {
            this._bunkerHitFx(m.position.x, m.position.y);
            consumed = true;
          }
          break;
        }
      }
      if (consumed) { this.playerBullets.releaseBullet(m); continue; }
      // Player bullets vs UFO (swept)
      if (this.ufo.containsSeg(m.prevX, m.prevY, m.position.x, m.position.y)) {
        this._onUfoKill(m.position.x, m.position.y);
        this.playerBullets.releaseBullet(m);
        continue;
      }
    }

    // Invader bullets vs player (swept)
    for (const m of iBullets) {
      if (this.player.alive && !this.player.shieldTime && !this.powerUpSystem.shielded()) {
        if (segCircle(m.prevX, m.prevY, m.position.x, m.position.y, this.player.x, BOUNDS.playerY, INVADER_BULLETS.radius + playerR)) {
          this._onPlayerHit(m.position.x, m.position.y);
          this.invaderBullets.releaseBullet(m);
          continue;
        }
      }
      // Invader bullets vs bunkers (swept)
      for (let i = 0; i < this.bunkers.bunkers.length; i++) {
        const b = this.bunkers.bunkers[i];
        if (b.isDestroyed) continue;
        const aabb = b.aabb();
        if (segAABB(m.prevX, m.prevY, m.position.x, m.position.y, aabb)) {
          const n = this.bunkers.erode(i, m.position.x, m.position.y, BUNKERS.erodeRadiusInvaderBullet, BUNKERS.erodeFalloff);
          if (n > 0) {
            this._bunkerHitFx(m.position.x, m.position.y);
            this.invaderBullets.releaseBullet(m);
          }
          break;
        }
      }
    }

    // Invaders eating bunkers (each live invader that overlaps a bunker erodes it)
    if (this.formation.alive > 0) {
      const positions = this.formation.livePositions();
      for (let i = 0; i < this.bunkers.bunkers.length; i++) {
        const b = this.bunkers.bunkers[i];
        if (b.isDestroyed) continue;
        const aabb = b.aabb();
        for (const p of positions) {
          if (p.y < aabb.minY - 1 || p.y > aabb.maxY + 1) continue;
          this.bunkers.eatInvader(i, pointAABB(p.x, p.y, FORMATION.bodyHalf));
        }
      }
    }

    // Power-up pickup
    for (const pu of livePU) {
      if (circleHit(pu.x, pu.y, 0.5, this.player.x, BOUNDS.playerY, playerR + 0.4)) {
        this._onPowerUp(pu.type, pu.x, pu.y);
        this.powerups.release(pu.mesh);
      }
    }
  }

  // ── Event handlers ─────────────────────────────────────────────
  _onInvaderHit(hit, x, y) {
    const result = this.formation.hitInvader(hit);
    if (result === 'armored') {
      this.audio.playSfx('hit', { volume: 0.5, pitch: 1.5 });
      this.particles.burst({ position: this._v3(x, y), count: 12, speed: 5, color: 0xffffff, size: 0.25, life: 0.4 });
      this.cameraRig.addTrauma(VFX.trauma.armorHit);
      return;
    }
    // Killed
    const base = [SCORING.squid, SCORING.crab, SCORING.lobster][hit.type];
    const pts = base * this.combo;
    this._addScore(pts);
    this.combo = Math.min(SCORING.maxCombo, this.combo + 1);
    this.hud.setCombo(this.combo);

    const color = [COLORS.squid, COLORS.crab, COLORS.lobster][hit.type];
    this.particles.burst({ position: this._v3(x, y), count: VFX.particles.invaderKill.sparks, speed: 8, color, size: 0.35, life: 0.7 });
    this.particles.burst({ position: this._v3(x, y), count: VFX.particles.invaderKill.debris, speed: 4, color: 0x888888, size: 0.2, life: 0.9, gravity: 6 });
    this.rings.spawn({ position: this._v3(x, y), maxRadius: 2.5, color, duration: 0.4 });
    this.text.spawn({ text: `+${pts}`, position: this._v3(x, y + 0.5), color: this._css(color), size: 1, life: 0.9 });
    if (this.combo >= 4) {
      this.text.spawn({ text: `COMBO ×${this.combo}`, position: this._v3(x, y + 1.2), color: '#ffd23d', size: 1.4, life: 1.1 });
    }
    this.cameraRig.addTrauma(VFX.trauma.invaderKill);
    this.loop.setTimescale(VFX.hitStop.invaderKill.scale, VFX.hitStop.invaderKill.ms);
    this.audio.playSfx('explosion', { volume: 0.6, pitch: 1 });
    this.input.vibrate(0.3, 80);

    // Power-up drop
    if (Math.random() < POWERUPS.dropChance) {
      this.powerups.spawn(x, y);
    }
  }

  _onPlayerHit(x, y) {
    this.lives--;
    this.combo = 1;
    this.hud.setLives(this.lives);
    this.hud.setCombo(1);
    this.hud.flashComboBreak();
    this.player.hit();
    this.particles.burst({ position: this._v3(x, y), count: VFX.particles.playerHit.sparks, speed: 10, color: COLORS.player, size: 0.4, life: 0.8 });
    this.particles.burst({ position: this._v3(x, y), count: VFX.particles.playerHit.debris, speed: 5, color: 0x888888, size: 0.25, life: 1.0, gravity: 8 });
    this.particles.burst({ position: this._v3(x, y), count: VFX.particles.playerHit.smoke, speed: 2, color: 0x444444, size: 0.6, life: 1.2 });
    this.rings.spawn({ position: this._v3(x, y), maxRadius: 4, color: COLORS.player, duration: 0.5 });
    this.cameraRig.addTrauma(VFX.trauma.playerHit);
    this.loop.setTimescale(VFX.hitStop.playerHit.scale, VFX.hitStop.playerHit.ms);
    this.audio.playSfx('explosion', { volume: 0.9, pitch: 0.8 });
    this.input.vibrate(0.8, 200);

    if (this.lives <= 0) {
      this._gameOver();
    } else {
      // Respawn with invulnerability
      this.player.reset(0);
      this.player.invulnerable = PLAYER.invulnTime;
    }
  }

  _onUfoKill(x, y) {
    const pts = this.ufo.score;
    this._addScore(pts);
    this.ufo._despawn();
    this.particles.burst({ position: this._v3(x, y), count: VFX.particles.ufoKill.sparks, speed: 9, color: COLORS.ufo, size: 0.4, life: 0.8 });
    this.particles.burst({ position: this._v3(x, y), count: VFX.particles.ufoKill.debris, speed: 4, color: 0x888888, size: 0.2, life: 1.0, gravity: 6 });
    this.rings.spawn({ position: this._v3(x, y), maxRadius: 5, color: COLORS.ufo, duration: 0.5 });
    this.text.spawn({ text: `+${pts}`, position: this._v3(x, y + 0.5), color: '#ff44aa', size: 1.3, life: 1.0 });
    this.cameraRig.addTrauma(VFX.trauma.ufoKill);
    this.loop.setTimescale(VFX.hitStop.ufoKill.scale, VFX.hitStop.ufoKill.ms);
    this.audio.playSfx('explosion', { volume: 0.8, pitch: 1.2 });
    this.input.vibrate(0.5, 120);
  }

  _onPowerUp(type, x, y) {
    this.audio.playSfx('powerup', { volume: 0.7 });
    this.particles.burst({ position: this._v3(x, y), count: 20, speed: 6, color: POWERUPS.types[type].color, size: 0.3, life: 0.6 });
    this.text.spawn({ text: type, position: this._v3(x, y + 0.5), color: this._css(POWERUPS.types[type].color), size: 1.1, life: 0.9 });

    if (type === 'NUKES') {
      this._nuke();
      return;
    }
    this.powerUpSystem.apply(type);
    if (type === 'SHIELD') this.player.shieldTime = POWERUPS.types.SHIELD.duration;
  }

  _nuke() {
    const n = this.formation.clearAll();
    const pts = n * 10;
    this._addScore(pts);
    this.particles.burst({ position: this._v3(0, 3), count: VFX.particles.nuke.sparks, speed: 14, color: 0xff3355, size: 0.5, life: 1.0 });
    this.particles.burst({ position: this._v3(0, 3), count: VFX.particles.nuke.debris, speed: 8, color: 0x888888, size: 0.3, life: 1.2, gravity: 6 });
    this.particles.burst({ position: this._v3(0, 3), count: VFX.particles.nuke.smoke, speed: 3, color: 0x444444, size: 0.8, life: 1.5 });
    this.rings.spawn({ position: this._v3(0, 3), maxRadius: 12, color: 0xff3355, duration: 0.8 });
    this.cameraRig.addTrauma(VFX.trauma.nuke);
    this.loop.setTimescale(VFX.hitStop.nuke.scale, VFX.hitStop.nuke.ms);
    this.audio.playSfx('nuke', { volume: 1.0 });
    this.input.vibrate(1.0, 400);
    this.text.spawn({ text: `NUKE +${pts}`, position: this._v3(0, 4), color: '#ff3355', size: 1.6, life: 1.2 });
  }

  _bunkerHitFx(x, y) {
    this.particles.burst({ position: this._v3(x, y), count: 8, speed: 4, color: COLORS.bunker, size: 0.2, life: 0.5 });
    this.cameraRig.addTrauma(VFX.trauma.bunkerHit);
    this.audio.playSfx('hit', { volume: 0.3, pitch: 0.8 });
  }

  // ── Helpers ────────────────────────────────────────────────────
  _addScore(pts) {
    this.score = Math.min(SCORING.maxScore, this.score + pts);
    this.hud.setScore(this.score);
    if (this.score > this.highScore) {
      this.highScore = this.score;
      this.hud.setHigh(this.highScore);
    }
  }

  _banner(text) {
    this.text.spawn({ text, position: this._v3(0, 2), color: '#7df9ff', size: 1.8, life: 1.4, mode: 'html' });
  }

  _v3(x, y) { return new THREE.Vector3(x, y, 0); }

  _css(hex) {
    return `#${(hex & 0xffffff).toString(16).padStart(6, '0')}`;
  }

  _loadHigh() {
    try { return parseInt(localStorage.getItem(HS_KEY) || '0', 10) || 0; } catch { return 0; }
  }
  _saveHigh(v) {
    try { localStorage.setItem(HS_KEY, String(v)); } catch { /* ignore */ }
  }

  _togglePause() {
    if (this.state === 'PLAYING') this._setPaused(true);
    else if (this.state === 'PAUSED') this._setPaused(false);
  }

  _onStart() {
    if (this.state === 'READY') this._startGame();
    else if (this.state === 'PAUSED') this._setPaused(false);
    else if (this.state === 'GAMEOVER') this._showReady();
  }

  // ── UI panels ──────────────────────────────────────────────────
  _buildReadyPanel() {
    const p = new GlassUI({ parent: this.root, title: 'SPACE INVADERS', position: 'center' });
    p.setStat('HIGH SCORE', '000000');
    p.hint('WASD / Arrows to move · Space to fire · P to pause');
    p.button('START', () => this._startGame(), 'glow-magenta');
    p.hide();
    this._readyPanel = p;
    return p;
  }

  _buildPausePanel() {
    const p = new GlassUI({ parent: this.root, title: 'PAUSED', position: 'center' });
    p.button('RESUME', () => this._setPaused(false));
    p.button('QUIT', () => this._showReady(), 'glow-magenta');
    p.hide();
    this._pausePanel = p;
    return p;
  }

  _buildGameOverPanel() {
    const p = new GlassUI({ parent: this.root, title: 'GAME OVER', position: 'center' });
    p.setStat('SCORE', '000000');
    p.setStat('HIGH', '000000');
    p.button('PLAY AGAIN', () => this._showReady(), 'glow-magenta');
    p.hide();
    this._gameOverPanel = p;
    return p;
  }
}

import * as THREE from 'three';
import ObjectPool from '../../shared/core/ObjectPool.js';
import { BOUNDS, PLAYER, COLORS } from '../config.js';

/**
 * Pooled player bullets. One shared geometry + material; instances are plain
 * Meshes toggled by visibility. Each live bullet owns a motion trail
 * (attached on spawn, detached on release) via the shared MotionTrailPool.
 */
export default class PlayerBullet {
  /**
   * @param {THREE.Scene} scene
   * @param {import('../../shared/core/MemoryRegistry.js').MemoryRegistry} registry
   * @param {import('../../shared/vfx/MotionTrailPool.js').MotionTrailPool} [trailPool]
   */
  constructor(scene, registry, trailPool = null) {
    this.scene = scene;
    this.registry = registry;
    this.trailPool = trailPool;

    const geo = new THREE.CapsuleGeometry(PLAYER.bulletRadius, 0.5, 4, 8);
    const mat = new THREE.MeshStandardMaterial({
      color: 0xffffff,
      emissive: new THREE.Color(COLORS.playerBullet),
      emissiveIntensity: 2.2,
      metalness: 0.2,
      roughness: 0.3,
    });
    registry.track(geo);
    registry.track(mat);

    this.pool = new ObjectPool(
      () => {
        const m = new THREE.Mesh(geo, mat);
        m.visible = false;
        m.frustumCulled = false;
        scene.add(m);
        return m;
      },
      (m) => {
        m.visible = false;
        m.position.set(0, -999, 0);
      },
      PLAYER.bulletPoolSize
    );
  }

  /** Fire a bullet at (x, y). Returns the mesh. */
  fire(x, y) {
    const m = this.pool.acquire();
    m.visible = true;
    m.position.set(x, y, 0);
    m.rotation.set(0, 0, 0);
    if (this.trailPool) this.trailPool.attach(m, { length: 6, width: 0.2, color: COLORS.playerBullet });
    return m;
  }

  /** Release a specific bullet (detach its trail first). */
  releaseBullet(m) {
    if (this.trailPool) this.trailPool.detach(m);
    this.pool.release(m);
  }

  /** Advance all live bullets. Returns the list of live meshes (for collision). */
  update(dt) {
    const live = [];
    for (const m of this.pool.active) {
      if (!m.visible) continue;
      // Record the pre-move position so the game can run a swept (segment)
      // collision test — a fast bullet must not tunnel through a thin target.
      m.prevX = m.position.x;
      m.prevY = m.position.y;
      m.position.y += PLAYER.bulletSpeed * dt;
      if (m.position.y > BOUNDS.top + 2) {
        this.releaseBullet(m);
        continue;
      }
      live.push(m);
    }
    return live;
  }

  activeCount() {
    let n = 0;
    for (const m of this.pool.active) if (m.visible) n++;
    return n;
  }

  releaseAll() {
    for (const m of this.pool.active) if (this.trailPool) this.trailPool.detach(m);
    this.pool.releaseAll();
  }

  dispose() {
    for (const m of this.pool.free) this.scene.remove(m);
    for (const m of this.pool.active) this.scene.remove(m);
    // geo / mat disposed via registry
  }
}

import * as THREE from 'three';
import { damp, clamp } from '../../shared/math/Utils.js';
import { BOUNDS, PLAYER, COLORS } from '../config.js';

/**
 * Player cannon. 2D movement on the XY plane, banking from velocity,
 * PBR hull + procedural emissive canopy, engine glow that flares on fire.
 */
export default class PlayerShip {
  /**
   * @param {THREE.Scene} scene
   * @param {import('../../shared/core/MemoryRegistry.js').MemoryRegistry} registry
   */
  constructor(scene, registry) {
    this.scene = scene;
    this.registry = registry;

    this.x = 0;
    this.v = 0;
    this.cooldown = 0;
    this.shieldTime = 0;
    this.invulnerable = 0;
    this.engineFlare = 0;
    this.alive = true;
    this.fire = null; // set by game: (x, y) => void

    this.group = new THREE.Group();
    this.group.position.set(0, BOUNDS.playerY, 0);
    scene.add(this.group);

    const hullGeo = new THREE.ConeGeometry(0.85, 1.7, 4);
    hullGeo.rotateX(Math.PI / 2);
    hullGeo.rotateZ(Math.PI / 4);
    hullGeo.translate(0, 0.15, 0);
    const hullMat = new THREE.MeshStandardMaterial({
      color: 0x9fd8ff, metalness: 0.85, roughness: 0.25,
      emissive: 0x0a2a44, emissiveIntensity: 0.6,
    });
    this.hull = new THREE.Mesh(hullGeo, hullMat);
    this.group.add(this.hull);

    const finGeo = new THREE.BoxGeometry(1.7, 0.16, 0.5);
    const finMat = new THREE.MeshStandardMaterial({
      color: 0x113355, metalness: 0.7, roughness: 0.35,
      emissive: new THREE.Color(COLORS.player), emissiveIntensity: 1.4,
    });
    this.fin = new THREE.Mesh(finGeo, finMat);
    this.fin.position.y = -0.35;
    this.group.add(this.fin);

    const canopyGeo = new THREE.SphereGeometry(0.3, 16, 12);
    const canopyMat = new THREE.MeshStandardMaterial({
      color: 0x001122, metalness: 0.2, roughness: 0.1,
      emissive: new THREE.Color(COLORS.player), emissiveIntensity: 2.2,
    });
    this.canopy = new THREE.Mesh(canopyGeo, canopyMat);
    this.canopy.position.set(0, 0.55, 0);
    this.group.add(this.canopy);

    const engineGeo = new THREE.CircleGeometry(0.34, 20);
    const engineMat = new THREE.MeshStandardMaterial({
      color: 0x001018,
      emissive: new THREE.Color(0x66e0ff),
      emissiveIntensity: 1.4,
      metalness: 0.2,
      roughness: 0.5,
      transparent: true,
      opacity: 0.9,
      side: THREE.DoubleSide,
    });
    this.engine = new THREE.Mesh(engineGeo, engineMat);
    this.engine.position.set(0, -0.75, 0);
    this.group.add(this.engine);

    const shieldGeo = new THREE.SphereGeometry(1.5, 24, 16);
    const shieldMat = new THREE.MeshStandardMaterial({
      color: new THREE.Color(COLORS.player), metalness: 0.1, roughness: 0.1,
      emissive: new THREE.Color(COLORS.player), emissiveIntensity: 1.6,
      transparent: true, opacity: 0.22, depthWrite: false,
    });
    this.shield = new THREE.Mesh(shieldGeo, shieldMat);
    this.shield.visible = false;
    this.group.add(this.shield);

    registry.track(hullGeo); registry.track(hullMat);
    registry.track(finGeo); registry.track(finMat);
    registry.track(canopyGeo); registry.track(canopyMat);
    registry.track(engineGeo); registry.track(engineMat);
    registry.track(shieldGeo); registry.track(shieldMat);
  }

  reset(x = 0) {
    this.x = x;
    this.v = 0;
    this.cooldown = 0;
    this.shieldTime = 0;
    this.invulnerable = 0;
    this.alive = true;
    this.group.visible = true;
    this.group.position.set(x, BOUNDS.playerY, 0);
    this.group.rotation.set(0, 0, 0);
    this.shield.visible = false;
  }

  update(dt, inputAxisX, time) {
    if (!this.alive) return;
    const targetV = inputAxisX * PLAYER.maxSpeed;
    this.v = damp(this.v, targetV, PLAYER.damping, dt);
    this.x = clamp(this.x + this.v * dt, BOUNDS.left + 1, BOUNDS.right - 1);
    if (Math.abs(this.v) < 0.05) this.v = 0;

    this.group.position.x = this.x;
    this.group.rotation.z = -this.v * 0.02;

    this.cooldown = Math.max(0, this.cooldown - dt);
    this.invulnerable = Math.max(0, this.invulnerable - dt);
    this.shieldTime = Math.max(0, this.shieldTime - dt);
    this.engineFlare = Math.max(0, this.engineFlare - dt * 3);

    const blink = this.invulnerable > 0 && Math.floor(time * 14) % 2 === 0;
    this.hull.visible = !blink;
    this.fin.visible = !blink;
    this.canopy.visible = !blink;

    const pulse = 0.75 + Math.sin(time * 9) * 0.15 + this.engineFlare * 1.6;
    this.engine.scale.setScalar(pulse);
    this.canopy.material.emissiveIntensity = 1.8 + this.engineFlare * 2.0;

    this.shield.visible = this.shieldTime > 0;
    if (this.shield.visible) {
      const s = 1 + Math.sin(time * 6) * 0.04;
      this.shield.scale.setScalar(s);
      this.shield.material.opacity = 0.16 + Math.sin(time * 6) * 0.05;
    }
  }

  /** Try to fire. `cooldown` is the effective fire delay (RAPID-aware). */
  tryFire(cooldown = PLAYER.fireCooldown) {
    if (!this.alive || this.cooldown > 0) return false;
    this.cooldown = cooldown;
    this.engineFlare = 1;
    if (this.fire) this.fire(this.x, BOUNDS.playerY + 0.9);
    return true;
  }

  /** Mark the ship destroyed. Returns the impact point. */
  hit() {
    this.alive = false;
    this.group.visible = false;
    return { x: this.x, y: BOUNDS.playerY };
  }

  dispose() {
    this.scene.remove(this.group);
    // geometries / materials / textures disposed via registry
  }
}

/**
 * InputController — unified keyboard + Gamepad API.
 *
 * Identical semantics for both sources:
 *   axisX / axisY      — continuous movement (-1..1), deadzone 0.2
 *   firePressed        — edge-triggered (true for exactly one poll)
 *   fire               — level (held)
 *   pausePressed       — edge-triggered
 *   startPressed       — edge-triggered
 *   vibrate(i, ms)     — gamepad rumble (no-op without a pad)
 *
 * Poll once per frame from the game loop; edge state is consumed on poll.
 */
const DEADZONE = 0.2;

const KEY_MAP = {
  KeyW: 'up', ArrowUp: 'up',
  KeyS: 'down', ArrowDown: 'down',
  KeyA: 'left', ArrowLeft: 'left',
  KeyD: 'right', ArrowRight: 'right',
  Space: 'fire', KeyJ: 'fire',
  KeyP: 'pause', Escape: 'pause',
  Enter: 'start', KeyR: 'start',
};

function deadzone(v) {
  if (Math.abs(v) < DEADZONE) return 0;
  return (v - Math.sign(v) * DEADZONE) / (1 - DEADZONE);
}

export default class InputController {
  constructor() {
    this.isGamepadActive = false;
    this._keys = new Set();
    this._padIndex = null;
    this._pad = null;
    this._prevFire = false;
    this._prevPause = false;
    this._prevStart = false;
    this._firePressed = false;
    this._pausePressed = false;
    this._startPressed = false;
    this._onKeyDown = this._onKeyDown.bind(this);
    this._onKeyUp = this._onKeyUp.bind(this);
    this._onPad = this._onPad.bind(this);
    this._onBlur = this._onBlur.bind(this);
  }

  attach() {
    // keydown must be non-passive: we call preventDefault() for fire/pause/start
    // so Space/Enter don't scroll or re-trigger focused buttons.
    window.addEventListener('keydown', this._onKeyDown);
    window.addEventListener('keyup', this._onKeyUp, { passive: true });
    window.addEventListener('blur', this._onBlur);
    window.addEventListener('gamepadconnected', this._onPad);
    window.addEventListener('gamepaddisconnected', this._onPad);
    this._scanPads();
  }

  detach() {
    window.removeEventListener('keydown', this._onKeyDown);
    window.removeEventListener('keyup', this._onKeyUp);
    window.removeEventListener('blur', this._onBlur);
    window.removeEventListener('gamepadconnected', this._onPad);
    window.removeEventListener('gamepaddisconnected', this._onPad);
    this._keys.clear();
    this._pad = null;
    this._padIndex = null;
    this.isGamepadActive = false;
  }

  _onKeyDown(e) {
    const action = KEY_MAP[e.code];
    if (!action) return;
    if (action === 'fire' || action === 'start' || action === 'pause') e.preventDefault();
    this._keys.add(action);
  }

  _onKeyUp(e) {
    const action = KEY_MAP[e.code];
    if (action) this._keys.delete(action);
  }

  _onBlur() {
    this._keys.clear();
  }

  _onPad() {
    this._scanPads();
  }

  _scanPads() {
    const pads = navigator.getGamepads ? navigator.getGamepads() : [];
    let found = null;
    for (const p of pads) {
      if (p && p.connected) { found = p; break; }
    }
    this._pad = found;
    this._padIndex = found ? found.index : null;
    this.isGamepadActive = !!found;
  }

  _padAxis() {
    if (!this._pad) return { x: 0, y: 0 };
    const ax = this._pad.axes[0] || 0;
    const ay = this._pad.axes[1] || 0;
    return { x: deadzone(ax), y: deadzone(ay) };
  }

  _padButtons() {
    if (!this._pad) return { fire: false, pause: false, start: false };
    const b = this._pad.buttons;
    // A (0) = fire, B (1) = start, Start (9) = pause. Kept distinct so a
    // single press never triggers two actions at once.
    const fire = (b[0] && b[0].pressed) || (b[2] && b[2].pressed);
    const pause = b[9] && b[9].pressed;
    const start = b[1] && b[1].pressed;
    return { fire, pause, start };
  }

  /**
   * Poll once per frame. Returns a snapshot; edge flags are consumed here.
   */
  poll() {
    this._scanPads();
    const k = this._keys;
    const pad = this._padButtons();
    const axes = this._padAxis();

    const axisX = (k.has('right') ? 1 : 0) - (k.has('left') ? 1 : 0) + axes.x;
    const axisY = (k.has('down') ? 1 : 0) - (k.has('up') ? 1 : 0) + axes.y;

    const fire = k.has('fire') || pad.fire;
    const pause = k.has('pause') || pad.pause;
    const start = k.has('start') || pad.start;

    this._firePressed = fire && !this._prevFire;
    this._pausePressed = pause && !this._prevPause;
    this._startPressed = start && !this._prevStart;
    this._prevFire = fire;
    this._prevPause = pause;
    this._prevStart = start;

    return {
      axisX: Math.max(-1, Math.min(1, axisX)),
      axisY: Math.max(-1, Math.min(1, axisY)),
      fire,
      firePressed: this._firePressed,
      pause,
      pausePressed: this._pausePressed,
      start,
      startPressed: this._startPressed,
    };
  }

  /** Rumble: intensity 0..1, duration ms. No-op without a gamepad. */
  vibrate(intensity, ms) {
    if (!this._pad) return;
    const gp = this._pad;
    if (gp.vibrationActuator && gp.vibrationActuator.playEffect) {
      gp.vibrationActuator.playEffect('dual-rumble', {
        duration: ms,
        strongMagnitude: Math.min(1, intensity),
        weakMagnitude: Math.min(1, intensity * 0.6),
      }).catch(() => {});
    }
  }
}

import * as THREE from 'three';
import { clamp, lerp, easeOutQuad } from '../../shared/math/Utils.js';
import { makeInvaderAtlas } from '../../shared/textures/ProceduralTextures.js';
import { segCircleHit } from '../systems/CollisionSystem.js';
import { BOUNDS, FORMATION, COLORS, SCORING } from '../config.js';

// Classic invader pixel maps (1 = body pixel). 11 wide x 8 tall.
const PIXELS = {
  squid: [
    '....X.X....',
    '...X...X...',
    '..XXXXXXX..',
    '.XX.XXX.XX.',
    'XXXXXXXXXXX',
    'X.XXXXXXX.X',
    'X.X.....X.X',
    '...XX.XX...',
  ],
  crab: [
    '...X...X...',
    '..X.....X..',
    '..XXXXXXX..',
    '.XXX.XXX.XX',
    'XXXXXXXXXXX',
    'X.XXXXXXX.X',
    'X.X.....X.X',
    'XX.X...X.XX',
  ],
  lobster: [
    '.X..XXX..X.',
    'XX.XXXX.XXX',
    'XXXXXXXXXXX',
    'XXX.XXX.XXX',
    '.XXXXXXXXX.',
    '...X.X.X...',
    'X..X.X.X..X',
    'XX.X...X.XX',
  ],
};

// Frame B: toggle the limb pixels (rows 6-7) for the classic 2-frame march.
function frameB(rows) {
  const out = rows.slice();
  out[6] = out[6].split('').map((c, i) => (i % 2 === 0 ? (c === 'X' ? '.' : 'X') : c)).join('');
  out[7] = out[7].split('').map((c, i) => (i % 2 === 0 ? (c === 'X' ? '.' : 'X') : c)).join('');
  return out;
}

const TYPE_DEFS = [
  { key: 'squid', color: COLORS.squid, points: SCORING.squid },
  { key: 'crab', color: COLORS.crab, points: SCORING.crab },
  { key: 'lobster', color: COLORS.lobster, points: SCORING.lobster },
];

export default class InvaderFormation {
  /**
   * @param {THREE.Scene} scene
   * @param {import('../../shared/core/MemoryRegistry.js').MemoryRegistry} registry
   */
  constructor(scene, registry) {
    this.scene = scene;
    this.registry = registry;

    this.rows = FORMATION.rows;
    this.cols = FORMATION.cols;
    this.cellX = FORMATION.cellX;
    this.cellY = FORMATION.cellY;
    this.formW = (this.cols - 1) * this.cellX;

    this.dir = 1;
    this.stepT = 0;
    this.alive = 0;
    this.wave = 1;
    this.speedMul = 1; // set by the game each frame (SLOW power-up)

    // March interpolation state
    this.prevX = 0;
    this.prevY = 0;
    this.targetX = 0;
    this.targetY = 0;
    this.renderX = 0;
    this.renderY = 0;
    this.animT = 1;
    this.animDur = FORMATION.animTime;

    // Per-type instance data
    this.byType = TYPE_DEFS.map(() => ({ list: [], mesh: null, mat: null, texA: null, texB: null, frame: 0 }));

    this._dummy = new THREE.Object3D();
    this._flash = new Map(); // "type:index" -> remaining flash time
    this._flashColor = new THREE.Color(0xffffff);
    this._baseColors = TYPE_DEFS.map((d) => new THREE.Color(d.color));

    this._buildMeshes();
  }

  _buildMeshes() {
    const geo = new THREE.BoxGeometry(1.7, 1.4, 0.3);
    this.registry.track(geo);

    for (let t = 0; t < 3; t++) {
      const def = TYPE_DEFS[t];
      const texA = makeInvaderAtlas(PIXELS[def.key], def.color, this.registry);
      const texB = makeInvaderAtlas(frameB(PIXELS[def.key]), def.color, this.registry);
      const mat = new THREE.MeshStandardMaterial({
        map: texA,
        emissiveMap: texA,
        emissive: new THREE.Color(def.color),
        emissiveIntensity: 1.6,
        color: 0xffffff,
        metalness: 0.35,
        roughness: 0.4,
      });
      this.registry.track(mat);
      this.registry.track(texA);
      this.registry.track(texB);

      const mesh = new THREE.InstancedMesh(geo, mat, this.rows * this.cols);
      mesh.count = 0;
      mesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
      mesh.frustumCulled = false;
      this.scene.add(mesh);

      this.byType[t].mesh = mesh;
      this.byType[t].mat = mat;
      this.byType[t].texA = texA;
      this.byType[t].texB = texB;
    }
  }

  /** (Re)spawn the full formation for a wave. */
  reset(topY, wave) {
    for (let t = 0; t < 3; t++) this.byType[t].list.length = 0;
    this.alive = 0;
    this.dir = 1;
    this.stepT = 0;
    this.wave = wave;
    this._flash.clear();

    const left = -this.formW / 2;
    const armorChance = wave >= FORMATION.armorChanceFromWave ? FORMATION.armorChance : 0;
    for (let r = 0; r < this.rows; r++) {
      for (let c = 0; c < this.cols; c++) {
        const type = r === 0 ? 0 : r < 4 ? 1 : 2;
        const armored = Math.random() < armorChance;
        this.byType[type].list.push({
          row: r,
          col: c,
          hp: armored ? 2 : 1,
          baseX: left + c * this.cellX,
          baseY: -r * this.cellY,
        });
        this.alive++;
      }
    }

    this.targetX = left;
    this.targetY = topY;
    this.prevX = left;
    this.prevY = topY + 4; // fly in from above
    this.renderX = left;
    this.renderY = topY + 4;
    this.animT = 0;
    this.animDur = 0.9;

    this._writeAll();
  }

  /** Step interval from the acceleration curve (plan 1.3). */
  stepInterval() {
    const n = Math.max(1, this.alive);
    const tMax = Math.max(FORMATION.tMaxFloor, FORMATION.tMax - FORMATION.tMaxDropPerWave * (this.wave - 1));
    const base = FORMATION.tMin + (tMax - FORMATION.tMin) * Math.pow(n / (this.rows * this.cols), 0.7);
    // SLOW power-up lengthens the interval (speedMul >= 1).
    return base * (this.speedMul || 1);
  }

  /** March logic + render interpolation. */
  update(dt) {
    if (this.alive > 0 && this.animT >= 1) {
      this.stepT += dt;
      if (this.stepT >= this.stepInterval()) {
        this.stepT = 0;
        this._doStep();
      }
    }

    if (this.animT < 1) {
      this.animT = Math.min(1, this.animT + dt / this.animDur);
      const k = easeOutQuad(this.animT);
      this.renderX = lerp(this.prevX, this.targetX, k);
      this.renderY = lerp(this.prevY, this.targetY, k);
      this._writeAll();
    }

    if (this._flash.size > 0) {
      for (const [key, t] of this._flash) {
        const nt = t - dt;
        if (nt <= 0) {
          this._flash.delete(key);
          const [ti, idx] = key.split(':').map(Number);
          this.byType[ti].mesh.setColorAt(idx, this._baseColors[ti]);
          this.byType[ti].mesh.instanceColor.needsUpdate = true;
        } else {
          this._flash.set(key, nt);
        }
      }
    }
  }

  _doStep() {
    this.prevX = this.renderX;
    this.prevY = this.renderY;

    this.targetX += this.dir * FORMATION.stepX;
    if (this.dir > 0 && this.targetX + this.formW / 2 > BOUNDS.right) {
      this.targetX = BOUNDS.right - this.formW / 2;
      this.targetY -= FORMATION.drop;
      this.dir = -1;
    } else if (this.dir < 0 && this.targetX - this.formW / 2 < BOUNDS.left) {
      this.targetX = BOUNDS.left + this.formW / 2;
      this.targetY -= FORMATION.drop;
      this.dir = 1;
    }

    this.animT = 0;
    this.animDur = FORMATION.animTime;

    // 2-frame animation: swap the shared texture (all instances of a type in sync)
    for (let t = 0; t < 3; t++) {
      const bt = this.byType[t];
      bt.frame = 1 - bt.frame;
      const tex = bt.frame === 0 ? bt.texA : bt.texB;
      bt.mat.map = tex;
      bt.mat.emissiveMap = tex;
    }
  }

  _worldPos(inv) {
    return { x: this.renderX + inv.baseX, y: this.renderY + inv.baseY };
  }

  _writeAll() {
    const d = this._dummy;
    for (let t = 0; t < 3; t++) {
      const bt = this.byType[t];
      const list = bt.list;
      for (let i = 0; i < list.length; i++) {
        const p = this._worldPos(list[i]);
        d.position.set(p.x, p.y, 0);
        d.rotation.set(0, 0, 0);
        d.scale.set(1, 1, 1);
        d.updateMatrix();
        bt.mesh.setMatrixAt(i, d.matrix);
      }
      bt.mesh.count = list.length;
      bt.mesh.instanceMatrix.needsUpdate = true;
      if (bt.mesh.instanceColor) bt.mesh.instanceColor.needsUpdate = true;
    }
  }

  /** Find the invader at a world point (radius r). Returns {type, index} or null. */
  findInvader(x, y, r) {
    for (let t = 0; t < 3; t++) {
      const list = this.byType[t].list;
      for (let i = 0; i < list.length; i++) {
        const p = this._worldPos(list[i]);
        const dx = p.x - x;
        const dy = p.y - y;
        if (dx * dx + dy * dy <= r * r) return { type: t, index: i };
      }
    }
    return null;
  }

  /**
   * Swept find: test the segment (x0,y0)→(x1,y1) against every live invader
   * (circle radius r). Prevents fast bullets tunneling through a body in a
   * single frame. Returns {type, index} or null.
   */
  findInvaderSeg(x0, y0, x1, y1, r) {
    for (let t = 0; t < 3; t++) {
      const list = this.byType[t].list;
      for (let i = 0; i < list.length; i++) {
        const p = this._worldPos(list[i]);
        if (segCircleHit(x0, y0, x1, y1, p.x, p.y, r)) return { type: t, index: i };
      }
    }
    return null;
  }

  /** Kill (or armor-hit) the invader at {type, index}. Returns 'killed' | 'armored'. */
  hitInvader(hit) {
    const bt = this.byType[hit.type];
    const inv = bt.list[hit.index];
    inv.hp--;
    if (inv.hp > 0) {
      bt.mesh.setColorAt(hit.index, this._flashColor);
      bt.mesh.instanceColor.needsUpdate = true;
      this._flash.set(`${hit.type}:${hit.index}`, 0.12);
      return 'armored';
    }
    const last = bt.list.length - 1;
    bt.list[hit.index] = bt.list[last];
    bt.list.pop();
    this.alive--;
    // Reconcile flash state with the compaction swap so no slot is left
    // permanently tinted and the swapped-in invader keeps its own flash.
    const iKey = `${hit.type}:${hit.index}`;
    const lastKey = `${hit.type}:${last}`;
    if (this._flash.has(lastKey)) {
      this._flash.set(iKey, this._flash.get(lastKey));
      this._flash.delete(lastKey);
    } else {
      this._flash.delete(iKey);
      bt.mesh.setColorAt(hit.index, this._baseColors[hit.type]);
      bt.mesh.instanceColor.needsUpdate = true;
    }
    this._writeAll();
    return 'killed';
  }

  /** Lowest live invader y (for game-over check + bunker eating). */
  bottomY() {
    let minY = Infinity;
    for (let t = 0; t < 3; t++) {
      for (const inv of this.byType[t].list) {
        const p = this._worldPos(inv);
        if (p.y < minY) minY = p.y;
      }
    }
    return minY === Infinity ? -Infinity : minY;
  }

  /** World positions of every live invader (for bunker-eating overlap tests). */
  livePositions() {
    const out = [];
    for (let t = 0; t < 3; t++) {
      for (const inv of this.byType[t].list) {
        const p = this._worldPos(inv);
        out.push(p);
      }
    }
    return out;
  }

  /** Bottom-most live invader per column (for bullet source selection). */
  bottomByColumn() {
    const cols = new Array(this.cols).fill(null);
    for (let t = 0; t < 3; t++) {
      for (const inv of this.byType[t].list) {
        const p = this._worldPos(inv);
        const cur = cols[inv.col];
        if (!cur || p.y < cur.y) cols[inv.col] = p;
      }
    }
    return cols;
  }

  /** Destroy all invaders (nuke). Returns count. */
  clearAll() {
    const n = this.alive;
    for (let t = 0; t < 3; t++) {
      this.byType[t].list.length = 0;
      this.byType[t].mesh.count = 0;
      this.byType[t].mesh.instanceMatrix.needsUpdate = true;
    }
    this.alive = 0;
    this._flash.clear();
    return n;
  }

  dispose() {
    for (let t = 0; t < 3; t++) {
      const bt = this.byType[t];
      this.scene.remove(bt.mesh);
      bt.mesh.dispose();
    }
  }
}

/**
 * CollisionSystem — pure 2D collision tests on the XY plane (z ignored).
 *
 * The playfield is small (≤55 invaders, ≤8 player bullets, ≤24 invader
 * bullets), so a linear sweep with these cheap tests is faster than a
 * spatial hash at this scale and far simpler to keep correct. Every test is
 * a pure function of its inputs — no state, no allocation.
 */

/** Circle vs circle. */
export function circleHit(ax, ay, ar, bx, by, br) {
  const dx = ax - bx, dy = ay - by;
  const r = ar + br;
  return dx * dx + dy * dy <= r * r;
}

/** Point inside an AABB. */
export function pointInAABB(px, py, aabb) {
  return px >= aabb.minX && px <= aabb.maxX && py >= aabb.minY && py <= aabb.maxY;
}

/** AABB vs AABB overlap. */
export function aabbOverlap(a, b) {
  return a.minX < b.maxX && a.maxX > b.minX && a.minY < b.maxY && a.maxY > b.minY;
}

/**
 * Expand a point into a small AABB (for treating a bullet as a body when
 * testing against bunkers / the player).
 */
export function pointAABB(x, y, half) {
  return { minX: x - half, maxX: x + half, minY: y - half, maxY: y + half };
}

/**
 * Closest point on the segment (ax,ay)-(bx,by) to the point (px,py).
 * Used for swept collision so fast bullets cannot tunnel through thin
 * targets between frames.
 */
export function closestPointOnSegment(ax, ay, bx, by, px, py) {
  const abx = bx - ax, aby = by - ay;
  const apx = px - ax, apy = py - ay;
  const len2 = abx * abx + aby * aby;
  let t = len2 > 1e-9 ? (apx * abx + apy * aby) / len2 : 0;
  t = t < 0 ? 0 : t > 1 ? 1 : t;
  return { x: ax + abx * t, y: ay + aby * t };
}

/**
 * Swept circle test: does the segment (ax,ay)-(bx,by) come within `r` of
 * (cx,cy)? Returns the closest point on the segment (for effect placement)
 * or null if the segment misses the circle.
 */
export function segCircleHit(ax, ay, bx, by, cx, cy, r) {
  const cp = closestPointOnSegment(ax, ay, bx, by, cx, cy);
  const dx = cp.x - cx, dy = cp.y - cy;
  return dx * dx + dy * dy <= r * r ? cp : null;
}

/** Boolean swept circle test (segment vs circle). */
export function segCircle(ax, ay, bx, by, cx, cy, r) {
  return segCircleHit(ax, ay, bx, by, cx, cy, r) !== null;
}

/**
 * Swept AABB test: does the segment (ax,ay)-(bx,by) intersect the AABB?
 * (Slab method — robust for axis-aligned boxes.)
 */
export function segAABB(ax, ay, bx, by, aabb) {
  const dx = bx - ax, dy = by - ay;
  let tmin = 0, tmax = 1;
  for (const [o, d, lo, hi] of [
    [ax, dx, aabb.minX, aabb.maxX],
    [ay, dy, aabb.minY, aabb.maxY],
  ]) {
    if (Math.abs(d) < 1e-9) {
      if (o < lo || o > hi) return false;
    } else {
      let t1 = (lo - o) / d;
      let t2 = (hi - o) / d;
      if (t1 > t2) { const tmp = t1; t1 = t2; t2 = tmp; }
      tmin = Math.max(tmin, t1);
      tmax = Math.min(tmax, t2);
      if (tmin > tmax) return false;
    }
  }
  return true;
}

import { FORMATION, INVADER_BULLETS, WAVES } from '../config.js';

/**
 * WaveSystem — pure difficulty curves as a function of the current wave.
 *
 * No state beyond the wave number; every getter is a pure function of `wave`.
 * The game reads these when spawning a wave and when choosing bullet behavior.
 */
export default class WaveSystem {
  constructor() {
    this.wave = 1;
  }

  setWave(n) {
    this.wave = Math.max(1, Math.min(WAVES.max, n | 0));
  }

  /** Formation top Y for this wave (descends as waves progress). */
  topY() {
    return Math.max(
      FORMATION.topFloorY,
      FORMATION.topStartY - FORMATION.topDropPerWave * (this.wave - 1)
    );
  }

  /** March step-interval ceiling (faster march on later waves). */
  tMax() {
    return Math.max(
      FORMATION.tMaxFloor,
      FORMATION.tMax - FORMATION.tMaxDropPerWave * (this.wave - 1)
    );
  }

  /** Invader bullet fire interval (seconds). */
  fireInterval() {
    return Math.max(
      INVADER_BULLETS.minInterval,
      INVADER_BULLETS.baseInterval - INVADER_BULLETS.intervalDropPerWave * (this.wave - 1)
    );
  }

  /** Invader bullet speed (u/s). */
  bulletSpeed() {
    return Math.min(
      INVADER_BULLETS.maxSpeed,
      INVADER_BULLETS.baseSpeed + INVADER_BULLETS.speedPerWave * this.wave
    );
  }

  /** Max simultaneous invader bullets. */
  maxBullets() {
    return Math.min(
      INVADER_BULLETS.maxActiveCap,
      INVADER_BULLETS.maxActiveBase + INVADER_BULLETS.maxActivePerWave * this.wave
    );
  }

  /** Probability a spawned bullet is a zigzag. */
  zigzagChance() {
    return this.wave >= INVADER_BULLETS.zigzagFromWave ? INVADER_BULLETS.zigzagChance : 0;
  }

  /** Probability a spawned bullet is a seeker. */
  seekerChance() {
    return this.wave >= INVADER_BULLETS.seekerFromWave ? INVADER_BULLETS.seekerChance : 0;
  }

  /** Probability an invader is armored (2 HP). */
  armorChance() {
    return this.wave >= FORMATION.armorChanceFromWave ? FORMATION.armorChance : 0;
  }

  /** Wave-clear bonus. */
  waveBonus() {
    return 500 * this.wave;
  }

  /** True when this is the final wave (difficulty holds, no further scaling). */
  isFinal() {
    return this.wave >= WAVES.max;
  }
}

import * as THREE from 'three';
import { BOUNDS, BUNKERS, COLORS } from '../config.js';

/**
 * BunkerManager — four defensive shields, each a grid of small cells.
 *
 * All four bunkers share ONE geometry, ONE material, and ONE InstancedMesh
 * (one draw call for every bunker cell on screen). Erosion flips cells dead
 * and rewrites the instance matrices in place — no geometry churn, no leaks.
 *
 * Public surface:
 *   - bunkers: Bunker[]            (per-bunker cell logic + aabb)
 *   - aabb(i)                      world bounds of bunker i
 *   - cellAt(i, x, y)              true if a live cell covers the point
 *   - erode(i, x, y, r, falloff)   destroy cells within radius r
 *   - eatInvader(i, invAabb)       destroy cells overlapping an invader
 *   - anyAlive()                   true if any bunker still has cells
 *   - reset()                      rebuild all four bunkers
 *   - dispose()
 */

class Bunker {
  constructor(centerX) {
    this.centerX = centerX;
    this.centerY = BOUNDS.bunkerY;
    this.W = BUNKERS.gridW;
    this.H = BUNKERS.gridH;
    this.cell = BUNKERS.cell;
    this.width = this.W * this.cell;
    this.height = this.H * this.cell;

    // Classic trapezoid: flat top, sloped sides, notched bottom.
    this.mask = new Uint8Array(this.W * this.H);
    for (let y = 0; y < this.H; y++) {
      for (let x = 0; x < this.W; x++) {
        const nx = x / (this.W - 1);
        const ny = y / (this.H - 1);
        const leftEdge = 0.16 * (1 - ny);
        const rightEdge = 1 - 0.16 * (1 - ny);
        let on = nx >= leftEdge && nx <= rightEdge;
        if (ny > 0.72 && (nx < 0.32 || nx > 0.68)) on = false;
        this.mask[y * this.W + x] = on ? 1 : 0;
      }
    }
    this.alive = new Uint8Array(this.W * this.H);
    this.alive.set(this.mask);
    this.aliveCount = this.alive.reduce((a, b) => a + b, 0);
  }

  cellCenter(cx, cy) {
    const x = this.centerX - this.width / 2 + (cx + 0.5) * this.cell;
    const y = this.centerY - this.height / 2 + (cy + 0.5) * this.cell;
    return { x, y };
  }

  aabb() {
    return {
      minX: this.centerX - this.width / 2,
      maxX: this.centerX + this.width / 2,
      minY: this.centerY - this.height / 2,
      maxY: this.centerY + this.height / 2,
    };
  }

  cellAt(x, y) {
    const cx = Math.floor((x - (this.centerX - this.width / 2)) / this.cell);
    const cy = Math.floor((y - (this.centerY - this.height / 2)) / this.cell);
    if (cx < 0 || cx >= this.W || cy < 0 || cy >= this.H) return false;
    return this.alive[cy * this.W + cx] === 1;
  }

  erode(x, y, r, falloff = 0.25) {
    let destroyed = 0;
    let changed = false;
    const r2 = r * r;
    for (let cy = 0; cy < this.H; cy++) {
      for (let cx = 0; cx < this.W; cx++) {
        const idx = cy * this.W + cx;
        if (!this.alive[idx]) continue;
        const p = this.cellCenter(cx, cy);
        const dx = p.x - x, dy = p.y - y;
        if (dx * dx + dy * dy > r2) continue;
        const dist = Math.sqrt(dx * dx + dy * dy);
        if (dist > r * 0.6 && Math.random() < falloff) continue;
        this.alive[idx] = 0;
        this.aliveCount--;
        destroyed++;
        changed = true;
      }
    }
    if (changed) this._dirty = true;
    return destroyed;
  }

  eatInvader(invAabb) {
    let destroyed = 0;
    let changed = false;
    for (let cy = 0; cy < this.H; cy++) {
      for (let cx = 0; cx < this.W; cx++) {
        const idx = cy * this.W + cx;
        if (!this.alive[idx]) continue;
        const p = this.cellCenter(cx, cy);
        if (
          p.x >= invAabb.minX && p.x <= invAabb.maxX &&
          p.y >= invAabb.minY && p.y <= invAabb.maxY
        ) {
          this.alive[idx] = 0;
          this.aliveCount--;
          destroyed++;
          changed = true;
        }
      }
    }
    if (changed) this._dirty = true;
    return destroyed;
  }

  reset() {
    this.alive.set(this.mask);
    this.aliveCount = this.alive.reduce((a, b) => a + b, 0);
    this._dirty = true;
  }

  get isDestroyed() {
    return this.aliveCount <= 0;
  }
}

export default class BunkerManager {
  /**
   * @param {THREE.Scene} scene
   * @param {import('../../shared/core/MemoryRegistry.js').MemoryRegistry} registry
   */
  constructor(scene, registry) {
    this.scene = scene;
    this.registry = registry;

    const spacing = BUNKERS.spacing;
    const total = spacing * (BUNKERS.count - 1);
    const startX = -total / 2;
    this.bunkers = [];
    for (let i = 0; i < BUNKERS.count; i++) {
      this.bunkers.push(new Bunker(startX + i * spacing));
    }

    // Shared geometry + material (one draw call for all bunker cells).
    const geo = new THREE.BoxGeometry(1, 1, 1);
    const mat = new THREE.MeshStandardMaterial({
      color: 0xffffff, // instanceColor multiplies this for per-cell brightness
      emissive: new THREE.Color(COLORS.bunker),
      emissiveIntensity: 1.1,
      metalness: 0.3,
      roughness: 0.55,
    });
    registry.track(geo);
    registry.track(mat);
    this._geo = geo;
    this._mat = mat;

    const maxCells = this.bunkers.reduce((a, b) => a + b.W * b.H, 0);
    this.mesh = new THREE.InstancedMesh(geo, mat, maxCells);
    this.mesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
    this.mesh.frustumCulled = false;
    scene.add(this.mesh);

    this._dummy = new THREE.Object3D();
    this._color = new THREE.Color();
    this._writeAll();
  }

  _writeAll() {
    const d = this._dummy;
    let i = 0;
    for (const b of this.bunkers) {
      for (let cy = 0; cy < b.H; cy++) {
        for (let cx = 0; cx < b.W; cx++) {
          if (!b.alive[cy * b.W + cx]) continue;
          const p = b.cellCenter(cx, cy);
          d.position.set(p.x, p.y, 0);
          d.rotation.set(0, 0, 0);
          d.scale.set(b.cell * 0.92, b.cell * 0.92, 0.4);
          d.updateMatrix();
          this.mesh.setMatrixAt(i, d.matrix);
          // Slight per-cell brightness variation for a hand-built look.
          const v = 0.85 + ((cx * 7 + cy * 13) % 5) * 0.05;
          this._color.setRGB(v, v, v);
          this.mesh.setColorAt(i, this._color);
          i++;
        }
      }
    }
    this.mesh.count = i;
    this.mesh.instanceMatrix.needsUpdate = true;
    if (this.mesh.instanceColor) this.mesh.instanceColor.needsUpdate = true;
  }

  /** Flush any pending erosion to the instance buffer (call once per frame). */
  flush() {
    if (this.bunkers.some((b) => b._dirty)) {
      for (const b of this.bunkers) b._dirty = false;
      this._writeAll();
    }
  }

  aabb(i) { return this.bunkers[i].aabb(); }
  cellAt(i, x, y) { return this.bunkers[i].cellAt(x, y); }
  erode(i, x, y, r, falloff) { return this.bunkers[i].erode(x, y, r, falloff); }
  eatInvader(i, invAabb) { return this.bunkers[i].eatInvader(invAabb); }

  anyAlive() { return this.bunkers.some((b) => !b.isDestroyed); }

  reset() {
    for (const b of this.bunkers) b.reset();
    this._writeAll();
  }

  dispose() {
    this.scene.remove(this.mesh);
    this.mesh.dispose();
    // geo / mat disposed via registry
  }
}

